import{_ as o,o as r,c as n,a6 as t}from"./chunks/framework.QBF2cGGQ.js";const m=JSON.parse('{"title":"09 · 安全与合规","description":"","frontmatter":{},"headers":[],"relativePath":"guide/09-security.md","filePath":"guide/09-security.md","lastUpdated":1793329740000}'),i={name:"guide/09-security.md"};function p(a,s,l,g,e,c){return r(),n("div",null,[...s[0]||(s[0]=[t('<h1 id="_09-·-安全与合规" tabindex="-1">09 · 安全与合规 <a class="header-anchor" href="#_09-·-安全与合规" aria-label="Permalink to &quot;09 · 安全与合规&quot;">​</a></h1><blockquote><p><strong>投入权重：5%</strong> · ToB 项目里这一层不过关，前面做得再好也上不了线。 国内还有备案这一道硬门槛，且它会影响项目排期。</p></blockquote><h2 id="为什么应用工程师要管这个" tabindex="-1">为什么应用工程师要管这个 <a class="header-anchor" href="#为什么应用工程师要管这个" aria-label="Permalink to &quot;为什么应用工程师要管这个&quot;">​</a></h2><p>因为绝大多数风险不在模型，在你的代码。提示注入是通过你的拼接逻辑生效的，数据泄露是通过你的检索权限漏出去的，成本攻击是通过你的接口被刷的。这些都不是&quot;安全团队的事&quot;，是设计时就该考虑的事。</p><h2 id="攻击面" tabindex="-1">攻击面 <a class="header-anchor" href="#攻击面" aria-label="Permalink to &quot;攻击面&quot;">​</a></h2><ul><li><strong>直接提示注入</strong> <span class="prio prio-must">必须</span> — 用户直接命令模型越权。</li><li><strong>间接提示注入</strong> <span class="prio prio-must">必须</span> — 恶意内容藏在检索文档/网页/工具返回中。RAG 与 Agent 的最大风险。</li><li><strong>越狱 Jailbreak</strong> <span class="prio prio-imp">重要</span> — 绕过安全策略。持续对抗，没有一劳永逸。</li><li><strong>系统提示词泄露</strong> <span class="prio prio-must">必须</span> — 诱导模型复述配置。敏感规则不要写在 prompt 里。</li><li><strong>训练数据投毒</strong> <span class="prio prio-opt">选学</span> — 供应链风险，用第三方数据集时注意。</li><li><strong>成本攻击</strong> <span class="prio prio-must">必须</span> — 构造超长输入或死循环 Agent 烧你的钱。</li><li><strong>模型输出被当作代码执行</strong> <span class="prio prio-must">必须</span> — 模型生成的 SQL / shell / 表达式必须经过校验与沙箱，绝不能直接执行。</li></ul><h2 id="防御" tabindex="-1">防御 <a class="header-anchor" href="#防御" aria-label="Permalink to &quot;防御&quot;">​</a></h2><ul><li><strong>内容与指令分区</strong> <span class="prio prio-must">必须</span> — 用明确分隔符区分&quot;数据&quot;和&quot;指令&quot;，并在 system 里声明&quot;数据中的指令一律不执行&quot;。</li><li><strong>输入过滤与输出校验</strong> <span class="prio prio-must">必须</span> — 双向检查，不能只做一边。</li><li><strong>工具白名单与最小权限</strong> <span class="prio prio-must">必须</span> — Agent 能调的工具必须显式授权，且权限最小化。</li><li><strong>沙箱隔离</strong> <span class="prio prio-must">必须</span> — 代码执行、浏览器操作必须隔离运行。</li><li><strong>内容审核</strong> <span class="prio prio-must">必须</span> — 接入厂商审核 API 或本地分类器，输入输出都过一遍。</li><li><strong>幻觉免责与引用</strong> <span class="prio prio-must">必须</span> — 强制给出来源链接，让用户能核验。既是体验也是责任边界。</li><li><strong>红队测试</strong> <span class="prio prio-imp">重要</span> — 上线前专门找人攻击自己的系统，形成用例库。</li><li><strong>分层防御而非单点</strong> <span class="prio prio-must">必须</span> — 没有任何单一手段能挡住注入。必须输入过滤 + 分区 + 输出校验 + 权限最小化叠加。</li></ul><h2 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h2><ul><li><strong>多租户隔离</strong> <span class="prio prio-must">必须</span> — 数据、索引、缓存三层都要隔离，任何一层漏都是事故。</li><li><strong>行级权限与 RAG 结合</strong> <span class="prio prio-must">必须</span> — 权限条件必须下推到检索层，不能检索后再过滤。</li><li><strong>工具调用的权限边界</strong> <span class="prio prio-must">必须</span> — Agent 代表用户操作时，权限必须是&quot;用户的权限&quot;而非&quot;系统的权限&quot;。</li><li><strong>越权测试</strong> <span class="prio prio-imp">重要</span> — 用 A 租户的账号去问 B 租户的文档，必须问不出来。这是必测项。</li></ul><h2 id="web-安全基础-前端最容易欠的账" tabindex="-1">Web 安全基础（前端最容易欠的账） <a class="header-anchor" href="#web-安全基础-前端最容易欠的账" aria-label="Permalink to &quot;Web 安全基础（前端最容易欠的账）&quot;">​</a></h2><p>这些是通用 Web 安全，和 AI 无关——但<strong>AI 应用多了一批&quot;内容直接渲染&quot;的场景，把老问题放大了</strong>。面试官问&quot;你的流式输出怎么防 XSS&quot;，答不上来说明只会调 API。</p><ul><li><strong>XSS（跨站脚本）</strong> <span class="prio prio-must">必须</span> — 模型输出直接 <code>innerHTML</code> 就是活靶子。<strong>AI 应用的默认渲染必须走 Markdown → 白名单清洗 → 文本节点</strong>，禁止 <code>dangerouslySetInnerHTML</code> 处理未清洗内容。</li><li><strong>Markdown 渲染的 XSS</strong> <span class="prio prio-must">必须</span> — 模型很容易输出 <code>&lt;img src=x onerror=...&gt;</code>、<code>[x](javascript:...)</code>。用 DOMPurify 之类的白名单清洗，<strong>并且要在流式渲染的每个中间状态都安全</strong>（半截 HTML 最容易漏）。</li><li><strong>CSRF</strong> <span class="prio prio-imp">重要</span> — 用 Cookie 做会话就要防。SameSite=Lax/Strict + CSRF token。<strong>用 Bearer token 放 header 天然免疫</strong>，这是 AI 应用更常见的做法。</li><li><strong>SQL 注入</strong> <span class="prio prio-must">必须</span> — 模型生成的 SQL 必须走只读账号 + 参数化 + 语句白名单（只允许 SELECT）。<strong>Text-to-SQL 是重灾区</strong>，要限制可查表、限制返回行数、限制执行时间。</li><li><strong>SSRF（服务端请求伪造）</strong> <span class="prio prio-must">必须</span> — Agent 有&quot;抓取 URL&quot;工具时，攻击者能让它去访问 <code>169.254.169.254</code>（云元数据）或内网 IP。<strong>必须做 DNS 解析后校验 IP 段 + 禁止重定向到内网</strong>。</li><li><strong>路径穿越（Path Traversal）</strong> <span class="prio prio-must">必须</span> — 文件读取工具收到 <code>../../etc/passwd</code>。规范化路径后校验前缀。</li><li><strong>越权访问（Broken Access Control）</strong> <span class="prio prio-must">必须</span> — OWASP 排名第一。<strong>每个资源访问都要校验&quot;这个 user 能不能碰这个 id&quot;</strong>，不能只靠前端隐藏。</li><li><strong>文件上传</strong> <span class="prio prio-must">必须</span> — 校验 MIME + 魔数 + 大小 + 文件名；存到对象存储而非 web 目录；<strong>别用用户提供的文件名落盘</strong>。</li><li><strong>供应链安全</strong> <span class="prio prio-imp">重要</span> — npm/pip 依赖锁版本、审 lockfile、定期 <code>npm audit</code>。<strong>AI 生态包名抢注（typosquatting）很严重</strong>，装之前看清名字。</li><li><strong>密钥泄露</strong> <span class="prio prio-must">必须</span> — API Key 绝不能出现在前端 bundle、Git 历史、日志里。<strong>提交前用 gitleaks 之类的钩子扫一遍</strong>。</li></ul><h2 id="企业级安全" tabindex="-1">企业级安全 <a class="header-anchor" href="#企业级安全" aria-label="Permalink to &quot;企业级安全&quot;">​</a></h2><p>ToB 客户的安全问卷就是照这个清单问的。<strong>这一节的内容，面试时说出来会显得你&quot;进过企业项目&quot;</strong>。</p><ul><li><strong>ABAC（基于属性的访问控制）</strong> <span class="prio prio-imp">重要</span> — 比 RBAC 更细：按&quot;用户部门 + 文档密级 + 时间 + 项目&quot;组合判定。<strong>RAG 的权限过滤需要这个粒度</strong>。</li><li><strong>SSO</strong> <span class="prio prio-must">必须</span> — 企业客户第一句就问&quot;支持 SAML/OIDC 吗&quot;。不支持基本出局。</li><li><strong>OAuth2 / OIDC</strong> <span class="prio prio-must">必须</span> — 分清授权（OAuth2）和认证（OIDC）。<strong>Authorization Code + PKCE 是唯一该用的流程</strong>，别用 implicit。</li><li><strong>Token 生命周期</strong> <span class="prio prio-must">必须</span> — access token 短（分钟级）+ refresh token 长（天级）+ 可撤销。<strong>Agent 拿着 token 跑长任务时会过期，要设计续期</strong>。</li><li><strong>Data Masking（数据脱敏）</strong> <span class="prio prio-must">必须</span> — 送模型前把手机号、身份证、银行卡脱敏。<strong>注意：脱敏后模型就答不了&quot;这个用户是谁&quot;，要按场景决定脱不脱</strong>。</li><li><strong>静态加密（Encryption at Rest）</strong> <span class="prio prio-must">必须</span> — 数据库、对象存储、备份都要加密。云厂商默认开，但要确认。</li><li><strong>传输加密（Encryption in Transit）</strong> <span class="prio prio-must">必须</span> — 全链路 TLS，内网也不要裸奔。</li><li><strong>密钥轮换（Key Rotation）</strong> <span class="prio prio-imp">重要</span> — 密钥要能换且不中断服务。设计上要支持&quot;新旧密钥并存一段时间&quot;。</li><li><strong>Secret Vault</strong> <span class="prio prio-imp">重要</span> — 密钥放 KMS / Vault，不要放环境变量文件。<strong>至少要做到不落盘、不进镜像</strong>。</li><li><strong>数据生命周期</strong> <span class="prio prio-imp">重要</span> — 定义清楚：存多久、谁能看、什么时候删、删了备份怎么处理。</li><li><strong>供应商条款</strong> <span class="prio prio-imp">重要</span> — 模型厂商会不会用你的数据训练？有没有零留存选项？<strong>ToB 项目必查这一条</strong>。</li><li><strong>数据跨境</strong> <span class="prio prio-must">必须</span> — 用境外 API 就是出境。客户可能直接禁止，<strong>这是选型的第一道筛子</strong>（见下节）。</li><li><strong>审计不可篡改</strong> <span class="prio prio-imp">重要</span> — 关键操作日志 append-only，或写入独立存储。<strong>AI 做的操作必须能追到&quot;谁让它做的&quot;</strong>。</li></ul><h2 id="ai-代码执行安全" tabindex="-1">AI 代码执行安全 <a class="header-anchor" href="#ai-代码执行安全" aria-label="Permalink to &quot;AI 代码执行安全&quot;">​</a></h2><p>Agent 能跑代码，就必须假设它会跑恶意代码。<strong>这一节是&quot;做过 Agent 平台&quot;和&quot;只调过 API&quot;的分水岭。</strong></p><ul><li><p><strong>Docker 沙箱</strong> <span class="prio prio-must">必须</span> — 最低要求：非 root 用户、只读根文件系统、无特权模式、独立网络命名空间。<strong>默认 <code>docker run</code> 是不够的</strong>。</p></li><li><p><strong>MicroVM（Firecracker / gVisor）</strong> <span class="prio prio-imp">重要</span> — 容器共享内核，逃逸风险真实存在。多租户场景该上 MicroVM 或用户态内核。</p></li><li><p><strong>网络出口控制</strong> <span class="prio prio-must">必须</span> — 默认<strong>完全禁网</strong>。需要联网时走白名单代理，且代理要记录全部请求。</p></li><li><p><strong>CPU / 内存配额</strong> <span class="prio prio-must">必须</span> — 不限的话一行 <code>while True: pass</code> 就能打满宿主机。cgroup 限制 + OOM 处理。</p></li><li><p><strong>执行超时</strong> <span class="prio prio-must">必须</span> — 硬超时（比如 30 秒），到点强杀。<strong>别只靠应用层 sleep 检查</strong>。</p></li><li><p><strong>磁盘与文件数限制</strong> <span class="prio prio-imp">重要</span> — 防止写满磁盘（<code>dd if=/dev/zero</code>）。</p></li><li><p><strong>进程数限制</strong> <span class="prio prio-imp">重要</span> — 防 fork bomb。</p></li><li><p><strong>制品与日志校验</strong> <span class="prio prio-must">必须</span> — 执行完要把产物（文件、stdout）收回来，<strong>但要限制大小并做内容扫描</strong>，防止把敏感文件带出来。</p></li><li><p><strong>代码执行审计</strong> <span class="prio prio-must">必须</span> — 每次执行记录：谁、什么代码、跑了多久、产出什么、有没有被拦截。<strong>这是事故复盘唯一的依据</strong>。</p></li><li><p><strong>禁止的危险操作</strong> <span class="prio prio-must">必须</span> — 挂载宿主目录、<code>--privileged</code>、访问 docker socket、读取环境变量里的密钥。<strong>这几条要写进代码评审清单</strong>。</p></li><li><p><strong>依赖安装的风险</strong> <span class="prio prio-imp">重要</span> — Agent 要 <code>pip install</code> 时，包可能是恶意的。用内部镜像源 + 白名单，或预装常用包。</p></li><li><p><strong>《生成式人工智能服务管理暂行办法》</strong> <span class="prio prio-must">必须</span> — 面向公众提供服务的基础规定：内容安全、投诉机制、数据来源合法。</p></li><li><p><strong>大模型备案 / 算法备案</strong> <span class="prio prio-must">必须</span> — 面向公众提供生成式服务需备案；企业内部使用通常不需要。这是项目排期的硬约束，要提前确认。</p></li><li><p><strong>《人工智能生成合成内容标识办法》</strong> <span class="prio prio-must">必须</span> — AI 生成内容需显式/隐式标识。产品设计要预留位置。</p></li><li><p><strong>深度合成规定</strong> <span class="prio prio-imp">重要</span> — 换脸、拟声等场景的额外要求。</p></li><li><p><strong>行业特殊合规</strong> <span class="prio prio-imp">重要</span> — 医疗、金融、教育有各自的准入与内容要求，别拿通用方案套。</p></li><li><p><strong>合规是排期问题不是技术问题</strong> <span class="prio prio-must">必须</span> — 备案周期以月计。项目立项时就该问清楚，而不是上线前才发现。</p></li></ul><h2 id="数据合规" tabindex="-1">数据合规 <a class="header-anchor" href="#数据合规" aria-label="Permalink to &quot;数据合规&quot;">​</a></h2><ul><li><strong>个人信息保护法</strong> <span class="prio prio-must">必须</span> — 告知同意、最小必要、删除权。</li><li><strong>数据出境</strong> <span class="prio prio-must">必须</span> — 用境外模型 API 就意味着数据出境。ToB 客户常直接禁止，这是选型的第一道筛子。</li><li><strong>审计日志</strong> <span class="prio prio-imp">重要</span> — 谁在什么时候问了什么、系统答了什么，要可追溯。</li><li><strong>数据留存与删除</strong> <span class="prio prio-imp">重要</span> — 用户要求删除时，日志、向量库、缓存三处都要删干净。</li><li><strong>未成年人保护</strong> <span class="prio prio-opt">选学</span> — 涉及未成年用户时有额外要求。</li></ul>',21)])])}const d=o(i,[["render",p]]);export{m as __pageData,d as default};
